The RPC does the count check and increment in one transaction, so concurrent requests can't slip past the limit. Want the SQL for it?

Fail closed here. This endpoint sends email to third parties, so if the limiter is down it's safer to reject than to allow unlimited sends. Return a 503 rather than 500 so the client knows it's temporary.

sql
create table invite_rate_limits (
  key text primary key,
  window_start timestamptz not null,
  count int not null
);

create function check_invite_rate_limit(p_user_id uuid, p_email text)
returns jsonb language plpgsql security definer as $$
declare
  u record; e record;
begin
  -- per-user: 10/hour
  insert into invite_rate_limits as r (key, window_start, count)
  values ('u:' || p_user_id, now(), 1)
  on conflict (key) do update set
    window_start = case when r.window_start < now() - interval '1 hour' then now() else r.window_start end,
    count = case when r.window_start < now() - interval '1 hour' then 1 else r.count + 1 end
  returning * into u;
  if u.count > 10 then
    return jsonb_build_object('ok', false, 'retry_after', extract(epoch from (u.window_start + interval '1 hour' - now()))::int);
  end if;

  -- per-email: 3/day
  insert into invite_rate_limits as r (key, window_start, count)
  values ('e:' || p_email, now(), 1)
  on conflict (key) do update set
    window_start = case when r.window_start < now() - interval '1 day' then now() else r.window_start end,
    count = case when r.window_start < now() - interval '1 day' then 1 else r.count + 1 end
  returning * into e;
  if e.count > 3 then
    return jsonb_build_object('ok', false, 'retry_after', extract(epoch from (e.window_start + interval '1 day' - now()))::int);
  end if;

  return jsonb_build_object('ok', true);
end $$;


